(function(){
  // Local proxy loader for glpk.js v4.0.1 — injects the CDN script so the app can load from a relative path.
  // This is not a full vendored minified library, but ensures ./glpk.min.js resolves and proxies to a known-working CDN.
  try {
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/glpk.js/4.0.1/glpk.min.js';
    s.async = true;
    s.onload = function(){
      console.info('glpk proxy loader fetched CDN script:', s.src);
    };
    s.onerror = function(e){
      console.warn('Failed to load glpk from CDN via proxy loader', e);
    };
    document.head.appendChild(s);
  } catch (e) {
    console.error('glpk proxy loader error', e);
  }
})();
